INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6650, 'transit visa', '/ˈtrænsɪt ˈviːzə/', 'noun', '{"zh-TW":["過境簽證"],"en":["a visa allowing passage through a country to a third destination"]}', NULL, 'apply for a transit visa / transit visa requirement', '[{"en":"Some nationalities require a transit visa to change planes.","zh-TW":"某些國籍需要過境簽證才能轉機。"},{"en":"Check if a transit visa is needed for your layover country.","zh-TW":"查看您的過境國家是否需要過境簽證。"}]', NULL, NULL, 4, 6650, NULL),
(6651, 'transition', '/trænˈzɪʃn/', 'noun, verb', '{"zh-TW":["過渡；轉型","過渡；轉變"],"en":["the process of changing from one state to another","to change"]}', NULL, 'smooth transition / transition period / transition to', '[{"en":"The transition to the new system took three months.","zh-TW":"過渡到新系統花了三個月。"},{"en":"We need to ensure a smooth transition.","zh-TW":"我們需要確保順利的過渡。"}]', '{"noun":"transition","verb":"transition","adjective":"transitional"}', NULL, 4, 6651, 470),
(6652, 'transition period', '/trænˈzɪʃən ˌpɪəriəd/', 'noun', '{"zh-TW":["過渡期"],"en":["a period during which a change is being phased in or implemented"]}', NULL, 'manage the transition period / transition period plan', '[{"en":"A six-month transition period allowed staff to adjust to new systems.","zh-TW":"六個月的過渡期允許員工適應新系統。"},{"en":"The transition period was extended after encountering implementation issues.","zh-TW":"遇到實施問題後，過渡期延長了。"}]', NULL, NULL, 5, 6652, NULL),
(6653, 'transitory', '/''trænsɪtəri/', 'adjective', '{"zh-TW":["短暫的；過渡性的"],"en":["not permanent; lasting only for a short time"]}', NULL, 'transitory phase / transitory effect / transitory nature', '[{"en":"The difficulties you are experiencing are transitory and will pass with time.","zh-TW":"你所經歷的困難是短暫的，隨著時間的推移將會過去。"},{"en":"The economic slowdown was described as transitory by central bank officials.","zh-TW":"中央銀行官員將經濟放緩描述為短暫現象。"}]', '{"adverb":"transitorily","noun":"transitoriness"}', NULL, 4, 6653, NULL),
(6654, 'translate', '/''trænsleɪt/', 'verb', '{"zh-TW":["翻譯；轉換"],"en":["to convert words or text from one language into another; to convert an idea into action"]}', NULL, 'translate a document / translate accurately / translate into', '[{"en":"She was hired to translate the technical manual from English into French.","zh-TW":"她被聘請將技術手冊從英文翻譯成法文。"},{"en":"Good translation requires not just language skills but cultural understanding as well.","zh-TW":"好的翻譯不僅需要語言技能，還需要文化理解。"}]', '{"noun":"translation","noun2":"translator"}', NULL, 3, 6654, NULL),
(6655, 'transliterate', '/''trænsˈlɪtəreɪt/', 'verb', '{"zh-TW":["音譯；字母轉換"],"en":["to write or print a letter or word using the closest corresponding letters of a different alphabet"]}', NULL, 'transliterate a name / transliterate from Japanese / transliterate into English', '[{"en":"The Chinese characters were transliterated into Roman letters for the English audience.","zh-TW":"漢字被音譯成羅馬字母，以方便英語讀者。"},{"en":"Transliterating foreign names helps readers pronounce them more accurately.","zh-TW":"音譯外國名字有助於讀者更準確地發音。"}]', '{"noun":"transliteration"}', NULL, 5, 6655, NULL),
(6656, 'transmit', '/trænzˈmɪt/', 'verb', '{"zh-TW":["傳送；傳輸"],"en":["to send or pass on from one place to another"]}', NULL, 'transmit data / transmit information / transmit electronically', '[{"en":"The system transmits data in real time.","zh-TW":"系統即時傳輸數據。"},{"en":"Reports are transmitted electronically to headquarters.","zh-TW":"報告以電子方式傳送到總部。"}]', '{"noun":"transmission, transmitter","verb":"transmit"}', NULL, 3, 6656, NULL),
(6657, 'transnationalism', '/ˌtrænzˈnæʃənəlɪzəm/', 'noun', '{"zh-TW":["跨國主義"],"en":["the phenomenon of living across multiple national borders and cultures"]}', NULL, 'transnationalism of migrants / cultural transnationalism / study transnationalism', '[{"en":"Transnationalism describes how migrants maintain ties to both origin and destination countries.","zh-TW":"跨國主義描述了移民如何維持與原籍國和目的地國的聯繫。"},{"en":"Digital communication has intensified transnationalism among diaspora communities.","zh-TW":"數字通信加強了僑民社區的跨國主義。"}]', '{"adjective":"transnational","adverb":"transnationally"}', NULL, 5, 6657, NULL),
(6658, 'transparency', '/trænsˈpærənsi/', 'noun', '{"zh-TW":["透明度；透明性"],"en":["the quality of being open and honest in business operations"]}', NULL, 'financial transparency / transparency in reporting', '[{"en":"Transparency builds trust with investors and the public.","zh-TW":"透明度建立與投資者和公眾的信任。"},{"en":"The report praised the company''s financial transparency.","zh-TW":"報告稱讚了公司的財務透明度。"}]', '{"adjective":"transparent","adverb":"transparently"}', NULL, 4, 6658, 943),
(6659, 'transparency report', '/trænsˈpærənsi rɪˌpɔːrt/', 'noun', '{"zh-TW":["透明度報告"],"en":["a document disclosing how an organization handles data and requests for information"]}', NULL, 'publish a transparency report / annual transparency report', '[{"en":"The tech company published a transparency report on government data requests.","zh-TW":"科技公司發布了一份關於政府資料請求的透明度報告。"},{"en":"Transparency reports help build trust with customers and regulators.","zh-TW":"透明度報告有助於建立客戶和監管機構的信任。"}]', NULL, NULL, 5, 6659, NULL),
(6660, 'transparency reporting', '/trænsˈpærənsi rɪˈpɔːrtɪŋ/', 'noun', '{"zh-TW":["透明度報告"],"en":["the disclosure of information about a company''s activities, risks, and environmental impact"]}', NULL, 'require transparency reporting / improve transparency reporting / sustainability and transparency reporting', '[{"en":"Investors increasingly demand transparency reporting on environmental and social risks.","zh-TW":"投資者越來越多地要求環境和社會風險方面的透明度報告。"},{"en":"Transparency reporting standards help stakeholders hold corporations accountable.","zh-TW":"透明度報告標準幫助利益相關者讓企業承擔責任。"}]', NULL, NULL, 5, 6660, NULL),
(6661, 'transparent', '/trænsˈpærənt/', 'adjective', '{"zh-TW":["透明的；公開的"],"en":["open and honest; easy to see through"]}', NULL, 'transparent process / transparent pricing / fully transparent', '[{"en":"The company maintains transparent accounting practices.","zh-TW":"公司維持透明的會計慣例。"},{"en":"We believe in transparent communication with stakeholders.","zh-TW":"我們相信與利害關係人的透明溝通。"}]', '{"noun":"transparency","adjective":"transparent","adverb":"transparently"}', NULL, 4, 6661, NULL),
(6662, 'transport', '/ˈtrænspɔːrt/', 'noun, verb', '{"zh-TW":["運輸；交通工具","運輸；運送"],"en":["the movement of goods or people","to carry from one place to another"]}', NULL, 'public transport / transport goods / transport costs', '[{"en":"Transport costs have risen significantly.","zh-TW":"運輸成本大幅上升。"},{"en":"Goods are transported by truck and rail.","zh-TW":"貨物透過卡車和鐵路運輸。"}]', '{"noun":"transport, transportation","verb":"transport"}', NULL, 3, 6662, NULL),
(6663, 'transportation', 'ˌtrænspɔːrˈteɪʃən', 'noun', '{"zh-TW":["運輸；交通","交通方式"],"en":["the movement of goods or people","a means of travel"]}', NULL, 'public transportation/transportation cost', '[{"en":"Transportation costs have increased this year.","zh-TW":"今年的運輸費用增加了。"}]', '{"verb":"transport","adjective":"transportable"}', NULL, 5, 6663, NULL),
(6664, 'transshipment', '/trænsˈʃɪpmənt/', 'noun', '{"zh-TW":["轉運；中轉"],"en":["the transfer of goods from one ship or vehicle to another"]}', NULL, 'transshipment hub / transshipment cost', '[{"en":"Singapore is a major transshipment hub in Asia.","zh-TW":"新加坡是亞洲主要的轉運樞紐。"},{"en":"Transshipment adds time and cost to the delivery process.","zh-TW":"轉運增加了配送過程的時間和成本。"}]', '{"verb":"transship","adjective":"transshipped"}', NULL, 5, 6664, NULL),
(6665, 'trauma', '/ˈtrɔːmə/', 'noun', '{"zh-TW":["創傷；外傷"],"en":["a deeply distressing experience; a physical injury"]}', NULL, 'physical trauma / emotional trauma / trauma center', '[{"en":"The accident caused significant physical trauma requiring surgery.","zh-TW":"事故造成了需要手術的嚴重身體創傷。"},{"en":"Psychological trauma from war affects veterans for years afterward.","zh-TW":"戰爭造成的心理創傷影響退伍軍人多年之後。"}]', '{"adjective":"traumatic","adverb":"traumatically"}', NULL, 2, 6665, NULL),
(6666, 'travel', 'ˈtrævəl', 'verb', '{"zh-TW":["旅行；出差","傳播"],"en":["to go from place to place","to move or spread"]}', NULL, 'travel for business/abroad', '[{"en":"She travels frequently for client meetings.","zh-TW":"她經常出差參加客戶會議。"}]', '{"noun":"travel, traveler","adjective":"traveling"}', NULL, 2, 6666, NULL),
(6667, 'travel adapter', '/ˈtrævəl əˈdæptər/', 'noun', '{"zh-TW":["旅行轉接頭；萬用插頭"],"en":["a device to connect electrical equipment in foreign countries"]}', NULL, 'bring a travel adapter / universal travel adapter', '[{"en":"Always bring a travel adapter when traveling abroad.","zh-TW":"出國旅行時務必攜帶旅行轉接頭。"},{"en":"A universal travel adapter works in most countries.","zh-TW":"萬用旅行轉接頭適用於大多數國家。"}]', NULL, NULL, 5, 6667, NULL),
(6668, 'travel advisory', '/''trævəl ədˌvaɪzəri/', 'noun', '{"zh-TW":["旅行警告；旅遊安全警示"],"en":["an official warning issued by a government about potential risks in a particular destination"]}', NULL, 'check travel advisories / issue a travel advisory / update travel advisory', '[{"en":"The government issued a travel advisory recommending caution in the region.","zh-TW":"政府發出了建議在該地區謹慎行事的旅行警告。"},{"en":"Travelers should check travel advisories before booking international trips.","zh-TW":"旅客在預訂國際旅行前應查閱旅行警告。"}]', NULL, NULL, 5, 6668, NULL),
(6669, 'travel agent', '/ˈtrævəl ˈeɪdʒənt/', 'noun', '{"zh-TW":["旅行社業務員；旅遊代理人"],"en":["a person or business that arranges travel"]}', NULL, 'consult a travel agent / book through a travel agent', '[{"en":"A travel agent helped them plan their honeymoon itinerary.","zh-TW":"旅行社業務員幫助他們規劃了蜜月行程。"},{"en":"Many people still prefer using a travel agent for complex trips.","zh-TW":"許多人仍偏好使用旅行社業務員安排複雜行程。"}]', NULL, NULL, 4, 6669, NULL),
(6670, 'travel allowance', '/ˈtrævəl əˈlaʊəns/', 'noun', '{"zh-TW":["差旅補貼"],"en":["a fixed amount paid to employees to cover travel-related costs"]}', NULL, 'claim a travel allowance / travel allowance policy', '[{"en":"Employees receive a daily travel allowance for business trips abroad.","zh-TW":"員工出差海外時每日收到差旅補貼。"},{"en":"The travel allowance covers transportation, accommodation, and meals.","zh-TW":"差旅補貼涵蓋交通、住宿和餐飲費用。"}]', NULL, NULL, 5, 6670, NULL),
(6671, 'travel blogger', '/''trævəl ˌblɒɡər/', 'noun', '{"zh-TW":["旅遊部落客；旅行部落格作者"],"en":["a person who documents and shares their travel experiences online"]}', NULL, 'popular travel blogger / professional travel blogger / travel blogger tips', '[{"en":"The travel blogger shared tips on budget travel in Southeast Asia.","zh-TW":"這位旅遊部落客分享了在東南亞省錢旅行的技巧。"},{"en":"She became a full-time travel blogger after her posts went viral.","zh-TW":"她在貼文爆紅後成為了全職旅遊部落客。"}]', NULL, NULL, 5, 6671, NULL),
(6672, 'travel companion', '/''trævəl kəmˌpæniən/', 'noun', '{"zh-TW":["旅行同伴"],"en":["a person who travels with you"]}', NULL, 'find a travel companion / good travel companion / solo versus with a travel companion', '[{"en":"Having a reliable travel companion made the long journey much more enjoyable.","zh-TW":"有一位可靠的旅行同伴使漫長的旅程更加愉快。"},{"en":"She found a travel companion through an online forum for solo female travelers.","zh-TW":"她通過一個女性獨自旅行者的在線論壇找到了旅行同伴。"}]', NULL, NULL, 5, 6672, NULL),
(6673, 'travel credit card', '/''trævəl ˌkredɪt kɑːrd/', 'noun', '{"zh-TW":["旅遊信用卡"],"en":["a credit card that offers travel-related rewards, such as airline miles or hotel points"]}', NULL, 'use a travel credit card / apply for a travel credit card / best travel credit card', '[{"en":"Using a travel credit card on everyday purchases helped her accumulate enough miles for a free flight.","zh-TW":"使用旅遊信用卡進行日常消費幫助她積累了足夠的里程兌換免費機票。"},{"en":"Travel credit cards often come with perks like travel insurance and airport lounge access.","zh-TW":"旅遊信用卡通常附帶旅遊保險和機場休息室使用等福利。"}]', NULL, NULL, 5, 6673, NULL),
(6674, 'travel delay', '/''trævəl dɪˈleɪ/', 'noun', '{"zh-TW":["旅途延誤；交通延誤"],"en":["a postponement of a scheduled journey or flight"]}', NULL, 'experience a travel delay / travel delay compensation / due to travel delay', '[{"en":"Passengers received meal vouchers due to the travel delay caused by bad weather.","zh-TW":"由於惡劣天氣造成的旅途延誤，旅客收到了餐飲券。"},{"en":"Travel delay insurance can reimburse you for additional expenses incurred.","zh-TW":"旅途延誤保險可以補償你因此產生的額外費用。"}]', NULL, NULL, 4, 6674, NULL),
(6675, 'travel diary', '/''trævəl ˌdaɪəri/', 'noun', '{"zh-TW":["旅行日記；遊記"],"en":["a personal record of events, experiences, and observations during a journey"]}', NULL, 'write a travel diary / keep a travel diary / publish a travel diary', '[{"en":"She kept a detailed travel diary of her year-long backpacking trip.","zh-TW":"她記錄了她為期一年的背包旅行的詳細旅行日記。"},{"en":"Her travel diary became the basis for a bestselling travel memoir.","zh-TW":"她的旅行日記成為了暢銷旅行回憶錄的基礎。"}]', NULL, NULL, 4, 6675, NULL),
(6676, 'travel document', '/ˈtrævəl ˈdɒkjʊmənt/', 'noun', '{"zh-TW":["旅行證件"],"en":["an official document required for international travel"]}', NULL, 'carry travel documents / required travel documents', '[{"en":"Keep all travel documents together in a safe place.","zh-TW":"將所有旅行證件放在安全的地方一起保管。"},{"en":"Losing travel documents abroad can cause serious problems.","zh-TW":"在國外遺失旅行證件可能造成嚴重問題。"}]', NULL, NULL, 5, 6676, NULL),
(6677, 'travel essentials', '/''trævəl ɪˌsenʃəlz/', 'noun', '{"zh-TW":["旅行必需品"],"en":["items considered necessary or highly useful for travel"]}', NULL, 'pack travel essentials / travel essentials checklist / forget travel essentials', '[{"en":"Her travel essentials always included a power bank, travel adapter, and small first aid kit.","zh-TW":"她的旅行必需品始終包括充電寶、旅行轉接頭和小型急救包。"},{"en":"A well-organized travel essentials bag saves time at security checkpoints.","zh-TW":"整理好的旅行必需品包可以在安全檢查站節省時間。"}]', NULL, NULL, 5, 6677, NULL),
(6678, 'travel expense', '/ˈtrævəl ɪkˈspens/', 'noun', '{"zh-TW":["差旅費；出差費用"],"en":["costs incurred while traveling for work purposes"]}', NULL, 'claim travel expenses / reimburse travel expenses / travel expense policy', '[{"en":"All travel expenses must be submitted within 30 days.","zh-TW":"所有差旅費必須在30天內提交報銷。"},{"en":"The company''s travel expense policy covers economy class for all flights.","zh-TW":"公司的差旅費政策涵蓋所有航班的經濟艙。"}]', '{"plural":"travel expenses"}', NULL, 5, 6678, NULL),
(6679, 'travel hack', '/''trævəl hæk/', 'noun', '{"zh-TW":["旅行技巧；省錢旅行妙招"],"en":["a tip or trick for saving money or making travel more convenient"]}', NULL, 'use a travel hack / share travel hacks / popular travel hack', '[{"en":"One popular travel hack is to book flights on Tuesday when prices are lowest.","zh-TW":"一個流行的旅行技巧是在週二機票價格最低時訂購機票。"},{"en":"She blogs about travel hacks that help her visit new countries on a tight budget.","zh-TW":"她寫部落格，分享幫助她以有限預算遊覽新國家的旅行技巧。"}]', NULL, NULL, 4, 6679, NULL),
(6680, 'travel insurance', '/ˈtrævəl ɪnˈʃʊərəns/', 'noun', '{"zh-TW":["旅遊保險"],"en":["insurance covering risks while traveling"]}', NULL, 'purchase travel insurance / travel insurance policy', '[{"en":"It is wise to purchase travel insurance before your trip.","zh-TW":"出行前購買旅遊保險是明智之舉。"},{"en":"Travel insurance covered her medical expenses abroad.","zh-TW":"旅遊保險支付了她在國外的醫療費用。"}]', '{"verb":"insure","adjective":"insured"}', NULL, 5, 6680, NULL),
(6681, 'travel insurance claim', '/''trævəl ɪnˌʃʊərəns kleɪm/', 'noun', '{"zh-TW":["旅遊保險索賠"],"en":["a formal request to an insurer for compensation for a travel-related loss or expense"]}', NULL, 'file a travel insurance claim / process a travel insurance claim', '[{"en":"She filed a travel insurance claim after her flight was cancelled.","zh-TW":"她在航班取消後提交了旅遊保險索賠。"},{"en":"The travel insurance claim was approved within two weeks of submission.","zh-TW":"旅遊保險索賠在提交後兩週內獲批准。"}]', NULL, NULL, 5, 6681, NULL),
(6682, 'travel itinerary', '/''trævəl aɪˌtɪnərəri/', 'noun', '{"zh-TW":["旅行行程表；行程安排"],"en":["a detailed plan of a journey, including dates, destinations, and activities"]}', NULL, 'create a travel itinerary / follow a travel itinerary / flexible travel itinerary', '[{"en":"She shared her travel itinerary with family members in case of an emergency.","zh-TW":"她與家人分享了旅行行程表，以備緊急情況。"},{"en":"A detailed travel itinerary ensures you make the most of every day on your trip.","zh-TW":"詳細的旅行行程表確保你充分利用旅行中的每一天。"}]', '{"noun":"itinerary"}', NULL, 5, 6682, NULL),
(6683, 'travel package', '/''trævəl ˌpækɪdʒ/', 'noun', '{"zh-TW":["旅遊套餐"],"en":["a bundle of travel services, typically including transportation, accommodation, and sometimes meals or activities"]}', NULL, 'book a travel package / all-inclusive travel package / travel package deal', '[{"en":"She booked an all-inclusive travel package that covered flights, hotel, and meals.","zh-TW":"她預訂了包含機票、飯店和餐食的全包式旅遊套餐。"},{"en":"Travel packages offer convenience and often work out cheaper than booking everything separately.","zh-TW":"旅遊套餐提供便利，通常比單獨預訂所有事項更便宜。"}]', '{"noun":"package"}', NULL, 5, 6683, NULL),
(6684, 'traveler''s check', '/''trævələrz tʃek/', 'noun', '{"zh-TW":["旅行支票"],"en":["a preprinted, fixed-amount check issued by a bank and designed to allow the person signing it to make an unconditional payment"]}', NULL, 'use traveler''s checks / cash a traveler''s check / issue traveler''s checks', '[{"en":"Traveler''s checks are a safe way to carry money abroad because they can be replaced if lost.","zh-TW":"旅行支票是攜帶海外資金的安全方式，因為如果丟失可以補辦。"},{"en":"Although less common today, traveler''s checks are still accepted at many international hotels.","zh-TW":"雖然今天不太常見，但旅行支票仍被許多國際酒店接受。"}]', NULL, NULL, 5, 6684, NULL),
(6685, 'travelogue', '/ˈtrævəlɒɡ/', 'noun', '{"zh-TW":["旅遊記述；旅遊日記"],"en":["a film, book, or talk about travel experiences"]}', NULL, 'write a travelogue / travel travelogue', '[{"en":"She wrote a travelogue about her year in Southeast Asia.","zh-TW":"她寫了一本關於她在東南亞一年的旅遊記述。"},{"en":"The travelogue inspired many readers to visit Japan.","zh-TW":"這本旅遊記述激發了許多讀者前往日本。"}]', NULL, NULL, 4, 6685, NULL),
(6686, 'Treasury bill', '/ˈtreʒəri bɪl/', 'noun', '{"zh-TW":["國庫券"],"en":["a short-term government debt security maturing in less than one year"]}', NULL, 'invest in Treasury bills / Treasury bill yield', '[{"en":"Treasury bills are considered risk-free investments in major economies.","zh-TW":"在主要經濟體中，國庫券被視為無風險投資。"},{"en":"Companies hold Treasury bills as part of their cash management strategy.","zh-TW":"公司持有國庫券作為其現金管理策略的一部分。"}]', '{"abbreviation":"T-bill"}', NULL, 5, 6686, NULL),
(6687, 'treasury bonds', '/ˈtreʒəri bɒndz/', 'noun', '{"zh-TW":["國庫債券；政府公債"],"en":["long-term government debt securities paying fixed interest"]}', NULL, 'invest in treasury bonds / yields on treasury bonds', '[{"en":"Investors shifted to treasury bonds during market volatility.","zh-TW":"市場波動期間，投資者轉向了國庫債券。"},{"en":"Treasury bond yields are used as a benchmark for other interest rates.","zh-TW":"國庫債券收益率被用作其他利率的基準。"}]', NULL, NULL, 5, 6687, NULL),
(6688, 'treasury function', '/ˈtreʒəri ˈfʌŋkʃən/', 'noun', '{"zh-TW":["財務管理職能；資金管理職能"],"en":["the function responsible for managing a company''s liquidity, cash, and financial risk"]}', NULL, 'manage the treasury function / centralize the treasury function', '[{"en":"The treasury function oversees currency hedging and short-term borrowing.","zh-TW":"財務管理職能負責監督貨幣對沖和短期借款。"},{"en":"Centralizing the treasury function improves visibility and control of cash.","zh-TW":"集中財務管理職能改善了現金的可視性和控制。"}]', NULL, NULL, 5, 6688, NULL),
(6689, 'treasury management', '/ˈtreʒəri ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["財資管理"],"en":["the management of a company cash flow, funding, and financial risk"]}', NULL, 'treasury management function / corporate treasury management', '[{"en":"The treasury management team hedged the company currency exposure.","zh-TW":"財資管理團隊對沖了公司的貨幣風險敞口。"},{"en":"Treasury management ensures the company has sufficient liquidity at all times.","zh-TW":"財資管理確保公司隨時有足夠的流動性。"}]', NULL, NULL, 5, 6689, NULL),
(6690, 'treasury stock', '/ˈtreʒəri stɒk/', 'noun', '{"zh-TW":["庫藏股"],"en":["shares previously issued by a company that have been repurchased and held"]}', NULL, 'hold treasury stock / cancel treasury stock', '[{"en":"The company holds treasury stock purchased during the buyback program.","zh-TW":"公司持有在回購計劃期間購買的庫藏股。"},{"en":"Treasury stock reduces the number of shares outstanding in the market.","zh-TW":"庫藏股減少了市場上流通的股份數量。"}]', NULL, NULL, 5, 6690, NULL),
(6691, 'treatment', '/ˈtriːtmənt/', 'noun', '{"zh-TW":["治療；處置"],"en":["medical care given to a patient"]}', NULL, 'receive treatment / course of treatment', '[{"en":"The treatment plan includes medication and rest.","zh-TW":"治療計劃包含藥物和休息。"},{"en":"Early treatment is key to a full recovery.","zh-TW":"及早治療是完全康復的關鍵。"}]', '{"verb":"treat","adjective":"treated"}', NULL, 3, 6691, NULL),
(6692, 'treaty', '/ˈtriːti/', 'noun', '{"zh-TW":["條約"],"en":["a formal agreement between countries"]}', NULL, 'peace treaty / sign a treaty', '[{"en":"The two countries signed a peace treaty.","zh-TW":"兩國簽署了和平條約。"},{"en":"The treaty was ratified by both nations.","zh-TW":"條約被兩國批准。"}]', NULL, NULL, 2, 6692, NULL),
(6693, 'trek', '/''trek/', 'verb', '{"zh-TW":["長途跋涉；徒步旅行"],"en":["to make a long and difficult journey, typically on foot"]}', NULL, 'trek through / mountain trek / jungle trek', '[{"en":"They trekked for three days through the rainforest to reach the village.","zh-TW":"他們在雨林中跋涉三天才到達村莊。"},{"en":"Trekking in Nepal offered breathtaking views of the Himalayas.","zh-TW":"在尼泊爾徒步旅行可以欣賞到令人嘆為觀止的喜馬拉雅山景色。"}]', '{"noun":"trekker"}', NULL, 1, 6693, NULL),
(6694, 'trekking', '/''trekɪŋ/', 'noun', '{"zh-TW":["徒步旅行；健走"],"en":["the activity of walking long distances on foot, especially over mountainous terrain"]}', NULL, 'go trekking / trekking gear / mountain trekking', '[{"en":"Trekking in Nepal is a dream for many adventure travelers.","zh-TW":"在尼泊爾徒步旅行是許多冒險旅行者的夢想。"},{"en":"Good trekking boots are essential to prevent blisters and ankle injuries.","zh-TW":"好的健走靴對防止水泡和腳踝受傷至關重要。"}]', '{"verb":"trek"}', NULL, 3, 6694, NULL),
(6695, 'trend', '/trend/', 'noun', '{"zh-TW":["趨勢；動向"],"en":["a general direction of change"]}', NULL, 'market trend / upward trend / follow a trend', '[{"en":"The trend toward remote work is accelerating.","zh-TW":"遠端工作的趨勢正在加速。"},{"en":"Market trends indicate growing consumer confidence.","zh-TW":"市場趨勢顯示消費者信心增長。"}]', '{"noun":"trend","adjective":"trending, trendy"}', NULL, 2, 6695, 471),
(6696, 'trend analysis', '/trɛnd əˈnælɪsɪs/', 'noun', '{"zh-TW":["趨勢分析"],"en":["the examination of data over time to identify patterns"]}', NULL, 'conduct a trend analysis / trend analysis report', '[{"en":"Trend analysis revealed a steady decline in customer complaints.","zh-TW":"趨勢分析顯示顧客投訴穩步下降。"},{"en":"Investors rely on trend analysis to make informed decisions.","zh-TW":"投資者依靠趨勢分析做出明智決策。"}]', NULL, NULL, 5, 6696, NULL),
(6697, 'triage', '/ˈtriːɑːʒ/', 'noun', '{"zh-TW":["分診；傷患分類"],"en":["the process of sorting patients based on urgency of treatment"]}', NULL, 'triage patients / triage system / emergency triage', '[{"en":"Nurses perform triage to prioritize the most critical patients first.","zh-TW":"護士進行分診以優先處理最緊急的患者。"},{"en":"The mass casualty triage protocol was activated after the accident.","zh-TW":"事故發生後啟動了大規模傷亡分診協議。"}]', '{"verb":"triage"}', NULL, 2, 6697, NULL),
(6698, 'trial balance', '/ˈtraɪəl ˈbæləns/', 'noun', '{"zh-TW":["試算表"],"en":["a bookkeeping worksheet listing all ledger balances to check accuracy"]}', NULL, 'prepare a trial balance / review the trial balance', '[{"en":"A trial balance is prepared at the end of each accounting period.","zh-TW":"每個會計期末編制試算表。"},{"en":"Errors in the trial balance led to a delay in the financial statements.","zh-TW":"試算表中的錯誤導致了財務報表的延遲。"}]', NULL, NULL, 5, 6698, NULL),
(6699, 'trial period', '/ˈtraɪəl ˈpɪəriəd/', 'noun', '{"zh-TW":["試用期"],"en":["a set period in which a product or employee is evaluated before full commitment"]}', NULL, 'offer a trial period / complete the trial period', '[{"en":"New employees undergo a 3-month trial period before confirmation.","zh-TW":"新員工在確認前接受3個月的試用期。"},{"en":"The software offers a 30-day trial period with full features.","zh-TW":"該軟件提供30天的全功能試用期。"}]', NULL, NULL, 4, 6699, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6700, 'trickle-down economics', '/ˈtrɪkəl daʊn ˌiːkəˈnɒmɪks/', 'noun', '{"zh-TW":["涓滴經濟學"],"en":["the theory that tax breaks for the wealthy will eventually benefit society as a whole"]}', NULL, 'criticize trickle-down economics / trickle-down economics theory / trickle-down effect', '[{"en":"Critics contend that trickle-down economics primarily benefits the wealthy without helping lower-income groups.","zh-TW":"批評者認為，涓滴經濟學主要讓富人受益，而無助於低收入群體。"},{"en":"Empirical studies have found little evidence that trickle-down economics reduces inequality.","zh-TW":"實證研究幾乎沒有發現涓滴經濟學能減少不平等的證據。"}]', NULL, NULL, 5, 6700, NULL),
(6701, 'trigger', '/ˈtrɪɡər/', 'noun, verb', '{"zh-TW":["觸發因素","觸發；引起"],"en":["something that causes an event","to cause something to happen"]}', NULL, 'trigger a response / trigger growth / trigger an alert', '[{"en":"The announcement triggered a sell-off in the market.","zh-TW":"該公告引發了市場拋售。"},{"en":"Rising costs triggered a review of the budget.","zh-TW":"成本上升觸發了對預算的審查。"}]', '{"noun":"trigger","verb":"trigger"}', NULL, 3, 6701, NULL),
(6702, 'trim', '/trɪm/', 'verb, noun', '{"zh-TW":["削減；修剪","修剪"],"en":["to reduce by cutting; to make neat","an act of cutting"]}', NULL, 'trim costs / trim the budget / trim expenses', '[{"en":"The company trimmed its workforce by 10%.","zh-TW":"公司裁減了10%的員工。"},{"en":"We need to trim unnecessary expenses.","zh-TW":"我們需要削減不必要的支出。"}]', '{"noun":"trim","verb":"trim"}', NULL, 1, 6702, NULL),
(6703, 'trip cancellation', '/''trɪp ˌkænsəˈleɪʃən/', 'noun', '{"zh-TW":["旅遊取消；行程取消"],"en":["the cancellation of a planned trip, often covered by travel insurance"]}', NULL, 'claim trip cancellation / trip cancellation insurance / due to trip cancellation', '[{"en":"Travel insurance covered the cost of the trip cancellation due to illness.","zh-TW":"旅遊保險涵蓋了因疾病而取消行程的費用。"},{"en":"Trip cancellation fees can be substantial if you book non-refundable tickets.","zh-TW":"如果你預訂不可退款的機票，旅遊取消費用可能相當高。"}]', NULL, NULL, 5, 6703, NULL),
(6704, 'triple', '/ˈtrɪpl/', 'adjective, verb', '{"zh-TW":["三倍的","增至三倍"],"en":["consisting of three parts","to become three times as much"]}', NULL, 'triple the amount / triple in value / triple digits', '[{"en":"Revenue tripled in just two years.","zh-TW":"營收在短短兩年內增長了三倍。"},{"en":"The company achieved triple-digit growth.","zh-TW":"公司實現了三位數的增長。"}]', '{"adjective":"triple","verb":"triple"}', NULL, 2, 6704, NULL),
(6705, 'triumph', '/ˈtraɪʌmf/', 'noun, verb', '{"zh-TW":["勝利；成就","獲勝"],"en":["a great victory or achievement","to achieve victory"]}', NULL, 'triumph over / a triumph of / personal triumph', '[{"en":"The product launch was a triumph for the team.","zh-TW":"產品發布是團隊的一大勝利。"},{"en":"The company triumphed over its competitors.","zh-TW":"公司戰勝了競爭對手。"}]', '{"noun":"triumph","verb":"triumph","adjective":"triumphant"}', NULL, 3, 6705, NULL),
(6706, 'trophy', '/ˈtroʊfi/', 'noun', '{"zh-TW":["獎盃"],"en":["a prize given to the winner"]}', NULL, 'trophy cabinet / lift the trophy', '[{"en":"The captain lifted the trophy.","zh-TW":"隊長舉起了獎盃。"},{"en":"They added another trophy to their collection.","zh-TW":"他們的收藏中又多了一座獎盃。"}]', NULL, NULL, 2, 6706, NULL),
(6707, 'tropical', '/ˈtrɒpɪkl/', 'adjective', '{"zh-TW":["熱帶的"],"en":["relating to the tropics; very hot and humid"]}', '{"root":{"text":"tropic","meaning":"turn (轉向)"},"suffix":{"text":"-al","meaning":"relating to (相關的)"},"logic":"源自太陽在回歸線「轉向」，指熱帶地區的。"}', 'tropical storm / tropical climate / tropical fruit', '[{"en":"Tropical storms are common in this region.","zh-TW":"熱帶風暴在這個地區很常見。"},{"en":"Bananas grow in tropical climates.","zh-TW":"香蕉生長在熱帶氣候中。"}]', '{"noun":"tropics"}', NULL, 3, 6707, NULL),
(6708, 'troubleshoot', '/ˈtrʌblʃuːt/', 'verb', '{"zh-TW":["排除故障；解決問題"],"en":["to identify and solve problems"]}', NULL, 'troubleshoot issues / troubleshoot a system / troubleshooting guide', '[{"en":"The IT team is troubleshooting the network issue.","zh-TW":"IT團隊正在排除網路故障。"},{"en":"Please refer to the troubleshooting guide.","zh-TW":"請參閱故障排除指南。"}]', '{"noun":"troubleshooting, troubleshooter","verb":"troubleshoot"}', NULL, 4, 6708, NULL),
(6709, 'truck driver', '/''trʌk ˌdraɪvər/', 'noun', '{"zh-TW":["卡車司機；貨車司機"],"en":["a person whose job is to drive a truck for delivering goods"]}', NULL, 'experienced truck driver / long-haul truck driver / hire a truck driver', '[{"en":"The truck driver completed a twelve-hour journey to deliver the goods on time.","zh-TW":"卡車司機完成了十二小時的旅程，準時送達貨物。"},{"en":"There is a growing shortage of truck drivers in many countries.","zh-TW":"許多國家的卡車司機短缺問題日益嚴重。"}]', NULL, NULL, 4, 6709, NULL),
(6710, 'trucking', '/''trʌkɪŋ/', 'noun', '{"zh-TW":["卡車運輸；公路運輸"],"en":["the business or process of transporting goods by truck"]}', NULL, 'domestic trucking / trucking company / trucking costs', '[{"en":"Trucking is the dominant form of freight transportation for domestic deliveries.","zh-TW":"公路運輸是國內配送最主要的貨運形式。"},{"en":"Rising fuel prices have significantly increased trucking costs across the industry.","zh-TW":"燃油價格上漲大幅增加了整個行業的公路運輸成本。"}]', '{"noun":"trucker"}', NULL, 3, 6710, NULL),
(6711, 'trust', '/trʌst/', 'noun, verb', '{"zh-TW":["信任；信託","信任；相信"],"en":["firm belief in reliability","to believe in the honesty of"]}', NULL, 'build trust / trust fund / mutual trust', '[{"en":"Building trust with customers takes time.","zh-TW":"與客戶建立信任需要時間。"},{"en":"We trust our suppliers to deliver on time.","zh-TW":"我們相信供應商會準時交貨。"}]', '{"noun":"trust, trustee","verb":"trust","adjective":"trustworthy, trusted"}', NULL, 2, 6711, NULL),
(6712, 'trust account', '/trʌst əˈkaʊnt/', 'noun', '{"zh-TW":["信託帳戶"],"en":["an account holding funds managed by a trustee on behalf of a beneficiary"]}', NULL, 'maintain a trust account / trust account balance', '[{"en":"Client funds are held in a separate trust account for legal protection.","zh-TW":"客戶資金保存在獨立的信託帳戶中以提供法律保護。"},{"en":"Real estate agents are legally required to use a trust account for deposits.","zh-TW":"房地產代理依法要求將訂金存入信託帳戶。"}]', NULL, NULL, 5, 6712, NULL),
(6713, 'trust fund', '/trʌst fʌnd/', 'noun', '{"zh-TW":["信托基金"],"en":["a legal arrangement where assets are held by one party for the benefit of another"]}', NULL, 'set up a trust fund / manage a trust fund / trust fund beneficiary', '[{"en":"A trust fund was established to provide for the education of the founder''s children.","zh-TW":"建立了一個信托基金，為創始人的孩子的教育提供資金。"},{"en":"Sovereign wealth trust funds invest national savings for future generations.","zh-TW":"主權財富信托基金為後代投資國家儲蓄。"}]', '{"noun2":"trustee"}', NULL, 4, 6713, NULL),
(6714, 'try', 'traɪ', 'verb', '{"zh-TW":["嘗試；努力","審判"],"en":["to make an effort to do","to test"]}', NULL, 'try a new approach', '[{"en":"Please try to complete the task today.","zh-TW":"請嘗試今天完成任務。"}]', '{"noun":"try, trial","adjective":"trying"}', NULL, 1, 6714, NULL),
(6715, 'tryout', '/''traɪˌaʊt/', 'noun', '{"zh-TW":["選拔測試；試訓"],"en":["a test of ability or performance, especially for a sports team"]}', NULL, 'go to a tryout / pass the tryout / attend a tryout', '[{"en":"She attended the university basketball tryout and earned a spot on the team.","zh-TW":"她參加了大學籃球選拔測試，並贏得了一個球隊名額。"},{"en":"The coach held tryouts to select the best players for the upcoming season.","zh-TW":"教練舉行了選拔測試，為即將到來的賽季選拔最佳球員。"}]', NULL, NULL, 2, 6715, NULL),
(6716, 'tsunami', '/tsuːˈnɑːmi/', 'noun', '{"zh-TW":["海嘯"],"en":["a very large ocean wave caused by an earthquake"]}', '{"root":{"text":"tsu-nami","meaning":"harbor wave (港灣的波浪)"},"logic":"源自日語「津波」（港灣的波浪）。"}', 'tsunami warning / trigger a tsunami', '[{"en":"The earthquake triggered a massive tsunami.","zh-TW":"地震引發了一場巨大的海嘯。"},{"en":"Coastal residents were evacuated after the tsunami warning.","zh-TW":"海嘯警報後沿海居民被疏散。"}]', NULL, NULL, 3, 6716, NULL),
(6717, 'tuition', '/tjuːˈɪʃən/', 'noun', '{"zh-TW":["學費；教學","學費"],"en":["money paid for instruction","teaching","the money paid for being taught"]}', NULL, 'tuition fee / tuition reimbursement; tuition fee / tuition waiver', '[{"en":"The company offers tuition reimbursement.","zh-TW":"公司提供學費補助。"},{"en":"Tuition fees have increased by 5%.","zh-TW":"學費上漲了5%。"},{"en":"Tuition costs keep rising.","zh-TW":"學費持續上漲。"},{"en":"She received a tuition waiver.","zh-TW":"她獲得了學費減免。"}]', '{"noun":"tuition"}', NULL, 3, 6717, NULL),
(6718, 'turboprop', '/ˈtɜːrbəʊprɒp/', 'noun', '{"zh-TW":["渦輪螺旋槳飛機"],"en":["an aircraft powered by turbine engines driving propellers"]}', NULL, 'turboprop aircraft / turboprop service', '[{"en":"The regional route is served by a turboprop aircraft.","zh-TW":"該地區航線由渦輪螺旋槳飛機提供服務。"},{"en":"Turboprop planes are common on short regional routes.","zh-TW":"渦輪螺旋槳飛機常見於短程地區航線。"}]', NULL, NULL, 3, 6718, NULL),
(6719, 'turbulence', '/ˈtɜːrbjʊləns/', 'noun', '{"zh-TW":["亂流；湍流"],"en":["irregular air movement causing an aircraft to shake"]}', NULL, 'encounter turbulence / severe turbulence', '[{"en":"The flight encountered turbulence over the mountains.","zh-TW":"飛機在山區遭遇亂流。"},{"en":"Fasten your seatbelt in case of turbulence.","zh-TW":"繫好安全帶以防亂流。"}]', '{"adjective":"turbulent"}', NULL, 4, 6719, NULL),
(6720, 'turmoil', '/''tɜːrmɔɪl/', 'noun', '{"zh-TW":["混亂；騷動；動盪"],"en":["a state of great disturbance, confusion, or uncertainty"]}', NULL, 'political turmoil / economic turmoil / in turmoil', '[{"en":"The country fell into political turmoil following the disputed election results.","zh-TW":"在有爭議的選舉結果之後，該國陷入了政治動盪。"},{"en":"The financial turmoil caused panic among investors worldwide.","zh-TW":"金融動盪在全球投資者中引發了恐慌。"}]', '{"adjective":"turbulent"}', NULL, 3, 6720, NULL),
(6721, 'turn', 'tɜːrn', 'verb', '{"zh-TW":["轉向；變成","輪到"],"en":["to change direction","to become"]}', NULL, 'turn down/around', '[{"en":"The company turned a profit last year.","zh-TW":"公司去年實現了盈利。"}]', '{"noun":"turn","adjective":"turning"}', NULL, 1, 6721, NULL),
(6722, 'turnaround', '/ˈtɜːrnaraʊnd/', 'noun', '{"zh-TW":["轉機；扭虧為盈"],"en":["a recovery from a difficult financial or operational situation"]}', NULL, 'business turnaround / corporate turnaround / turnaround plan / turnaround strategy', '[{"en":"The new CEO engineered a remarkable turnaround in two years.","zh-TW":"新執行長在兩年內創造了顯著的扭虧為盈。"},{"en":"The turnaround plan included cost cuts, new products, and leadership changes.","zh-TW":"轉機計劃包括成本削減、新產品和領導層變更。"}]', '{"verb":"turn around","adjective":"turnaround"}', NULL, 4, 6722, 944),
(6723, 'turnaround strategy', '/''tɜːrnəˌraʊnd ˌstrætədʒi/', 'noun', '{"zh-TW":["扭虧為盈策略；逆轉策略"],"en":["a plan developed to reverse a company''s decline and restore it to profitability"]}', NULL, 'implement a turnaround strategy / develop a turnaround strategy / successful turnaround strategy', '[{"en":"The board approved a bold turnaround strategy involving restructuring and cost reductions.","zh-TW":"董事會批准了一項涉及重組和成本削減的大膽逆轉策略。"},{"en":"Her leadership was instrumental in executing the company''s turnaround strategy.","zh-TW":"她的領導力在執行公司的逆轉策略中發揮了關鍵作用。"}]', '{"noun":"turnaround"}', NULL, 5, 6723, NULL),
(6724, 'turnaround time', '/''tɜːrnəˌraʊnd taɪm/', 'noun', '{"zh-TW":["周轉時間；完成時間"],"en":["the time it takes to complete a task or process and be ready to start again"]}', NULL, 'reduce turnaround time / improve turnaround time / fast turnaround time', '[{"en":"The factory improved its turnaround time by thirty percent through process automation.","zh-TW":"工廠通過流程自動化將周轉時間提高了三十%。"},{"en":"Customers expect a fast turnaround time when submitting service requests.","zh-TW":"客戶在提交服務請求時期望快速的周轉時間。"}]', NULL, NULL, 5, 6724, NULL),
(6725, 'turndown service', '/ˈtɜːrndaʊn ˈsɜːrvɪs/', 'noun', '{"zh-TW":["夜床服務；開床服務"],"en":["the evening hotel service of preparing the room for sleep"]}', NULL, 'request turndown service / premium turndown service', '[{"en":"Turndown service includes chocolates on the pillow.","zh-TW":"夜床服務包括在枕頭上放巧克力。"},{"en":"Premium rooms receive a complimentary turndown service each evening.","zh-TW":"高級客房每晚享有免費夜床服務。"}]', NULL, NULL, 5, 6725, NULL),
(6726, 'turnkey', '/ˈtɜːrnkiː/', 'adjective', '{"zh-TW":["交鑰匙的；即可使用的"],"en":["ready for immediate use after purchase or installation"]}', NULL, 'turnkey solution / turnkey project', '[{"en":"The company offered a turnkey solution for the factory setup.","zh-TW":"公司為工廠設置提供了交鑰匙解決方案。"},{"en":"A turnkey project is delivered ready for the client to operate.","zh-TW":"交鑰匙項目交付時即可供客戶運營。"}]', NULL, NULL, 3, 6726, NULL),
(6727, 'turnkey solution', '/ˈtɜːrnkiː səˈluːʃən/', 'noun', '{"zh-TW":["交鑰匙解決方案"],"en":["a complete ready-to-use system delivered to the customer"]}', NULL, 'provide a turnkey solution / turnkey solution provider', '[{"en":"The vendor offered a turnkey solution for the factory automation system.","zh-TW":"供應商為工廠自動化系統提供了交鑰匙解決方案。"},{"en":"Clients prefer turnkey solutions to avoid managing multiple vendors.","zh-TW":"客戶偏好交鑰匙解決方案以避免管理多個供應商。"}]', NULL, NULL, 5, 6727, NULL),
(6728, 'turnout', '/ˈtɜːrnaʊt/', 'noun', '{"zh-TW":["出席人數；參與率"],"en":["the number of people attending an event"]}', NULL, 'high turnout / voter turnout / expected turnout', '[{"en":"The conference had a higher turnout than expected.","zh-TW":"會議的出席人數超出預期。"},{"en":"Voter turnout was at an all-time high.","zh-TW":"投票率創下歷史新高。"}]', '{"noun":"turnout"}', NULL, 3, 6728, NULL),
(6729, 'turnover', '/ˈtɜːrnoʊvər/', 'noun', '{"zh-TW":["營業額；員工流動率"],"en":["the amount of business done; the rate of employee replacement"]}', NULL, 'staff turnover / annual turnover / high turnover', '[{"en":"The annual turnover reached $10 million.","zh-TW":"年營業額達到一千萬美元。"},{"en":"High staff turnover increases recruitment costs.","zh-TW":"高員工流動率增加了招募成本。"}]', '{"noun":"turnover"}', NULL, 3, 6729, 472),
(6730, 'turnover rate', '/ˈtɜːrnoʊvər reɪt/', 'noun', '{"zh-TW":["員工流動率"],"en":["the percentage of employees leaving a company in a given period"]}', NULL, 'employee turnover rate / reduce turnover rate / high turnover rate', '[{"en":"The company''s turnover rate fell after improving benefits.","zh-TW":"改善福利後，公司的員工流動率下降了。"},{"en":"A high turnover rate signals employee dissatisfaction.","zh-TW":"高員工流動率表明員工不滿意。"}]', NULL, NULL, 5, 6730, NULL),
(6731, 'turnround', '/ˈtɜːrnəraʊnd/', 'noun', '{"zh-TW":["週轉時間；好轉"],"en":["the time needed to complete a process; a recovery"]}', NULL, 'quick turnaround / turnaround time / business turnaround', '[{"en":"The turnaround time for orders is 48 hours.","zh-TW":"訂單的週轉時間為48小時。"},{"en":"The new CEO achieved a remarkable business turnaround.","zh-TW":"新任執行長實現了顯著的業務好轉。"}]', '{"noun":"turnaround"}', NULL, 3, 6731, NULL),
(6732, 'tutor', '/ˈtjuːtər/', 'noun', '{"zh-TW":["家教；導師","輔導"],"en":["a private teacher","to teach individually"]}', NULL, 'private tutor / math tutor; private tutor / tutor sessions / peer tutor', '[{"en":"She hired a math tutor.","zh-TW":"她請了一位數學家教。"},{"en":"The tutor helped him pass the exam.","zh-TW":"家教幫他通過了考試。"},{"en":"She hired a tutor to improve her English.","zh-TW":"她聘請了一位家教來提升英文。"},{"en":"Senior staff tutor new employees during onboarding.","zh-TW":"資深員工在入職期間輔導新員工。"}]', '{"verb":"tutor","noun2":"tutoring","noun":"tutor, tutorial, tutoring"}', NULL, 2, 6732, NULL),
(6733, 'tutorial', '/''tjuːˈtɔːriəl/', 'noun', '{"zh-TW":["輔導課；個別指導課"],"en":["a period of instruction given by a tutor to an individual or small group"]}', NULL, 'attend a tutorial / online tutorial / weekly tutorial', '[{"en":"She scheduled a tutorial with her professor to discuss her essay draft.","zh-TW":"她安排了與教授的輔導課，討論她的論文草稿。"},{"en":"The university offers free tutorials in mathematics for struggling students.","zh-TW":"大學為學習困難的學生提供免費的數學輔導課。"}]', '{"noun":"tutor","verb":"tutor"}', NULL, 3, 6733, NULL),
(6734, 'twin bed', '/twɪn bɛd/', 'noun', '{"zh-TW":["雙床（兩張單人床）"],"en":["a room with two single beds"]}', NULL, 'twin bed room / twin bed arrangement', '[{"en":"They requested a twin bed room to share as friends.","zh-TW":"他們作為朋友要求了雙床房間。"},{"en":"A twin bed configuration is ideal for business travelers sharing a room.","zh-TW":"雙床配置對於共享房間的商務旅客來說非常理想。"}]', NULL, NULL, 3, 6734, NULL),
(6735, 'two-factor authentication', '/tuː ˈfæktər ɔːˌθɛntɪˈkeɪʃən/', 'noun', '{"zh-TW":["雙重驗證"],"en":["a security process requiring two forms of verification"]}', NULL, 'enable two-factor authentication / two-factor authentication code', '[{"en":"Enable two-factor authentication for added account security.","zh-TW":"啟用雙重驗證以提高帳戶安全性。"},{"en":"Two-factor authentication greatly reduces the risk of unauthorized access.","zh-TW":"雙重驗證大大降低了未授權訪問的風險。"}]', '{"abbreviation":"2FA"}', NULL, 5, 6735, NULL),
(6736, 'two-way communication', '/tuː weɪ kəˌmjuːnɪˈkeɪʃən/', 'noun', '{"zh-TW":["雙向溝通"],"en":["communication where information flows in both directions between parties"]}', NULL, 'encourage two-way communication / two-way communication channel', '[{"en":"Good leadership requires two-way communication, not just top-down messages.","zh-TW":"良好的領導力需要雙向溝通，不僅僅是自上而下的信息。"},{"en":"The survey opened a channel for two-way communication with employees.","zh-TW":"調查開啟了與員工雙向溝通的渠道。"}]', NULL, NULL, 5, 6736, NULL),
(6737, 'type', 'taɪp', 'noun', '{"zh-TW":["類型；種類","字體"],"en":["a category or kind","printed characters"]}', NULL, 'type of/different types', '[{"en":"What type of service do you offer?","zh-TW":"您提供哪種類型的服務？"}]', '{"verb":"type","adjective":"typical","adverb":"typically"}', NULL, 1, 6737, NULL),
(6738, 'typhoon', '/taɪˈfuːn/', 'noun', '{"zh-TW":["颱風"],"en":["a tropical storm in the western Pacific"]}', '{"root":{"text":"typhoon","meaning":"great wind (大風)"},"logic":"源自中文「大風」或阿拉伯語 tufan。"}', 'typhoon season / typhoon warning', '[{"en":"The typhoon brought heavy rain and strong winds.","zh-TW":"颱風帶來暴雨和強風。"},{"en":"All flights were cancelled due to the typhoon.","zh-TW":"所有航班因颱風取消。"}]', NULL, NULL, 3, 6738, NULL),
(6739, 'typical', '/ˈtɪpɪkl/', 'adjective', '{"zh-TW":["典型的；代表性的"],"en":["having the distinctive qualities of a type"]}', NULL, 'typical example / typical day / typical customer', '[{"en":"A typical workday starts at 9 AM.","zh-TW":"典型的工作日從上午9點開始。"},{"en":"This is a typical example of market fluctuation.","zh-TW":"這是市場波動的典型例子。"}]', '{"adjective":"typical","adverb":"typically"}', NULL, 3, 6739, NULL),
(6740, 'ubiquitous', '/juːˈbɪkwɪtəs/', 'adjective', '{"zh-TW":["無所不在的；普遍存在的"],"en":["present, appearing, or found everywhere"]}', NULL, 'ubiquitous technology / ubiquitous presence / ubiquitous feature', '[{"en":"Smartphones have become ubiquitous in modern society.","zh-TW":"智慧型手機在現代社會中已無所不在。"},{"en":"The term ''synergy'' became ubiquitous in business circles.","zh-TW":"「協同效應」這個詞在商業圈中變得無處不在。"}]', '{"noun":"ubiquity","adverb":"ubiquitously"}', NULL, 4, 6740, NULL),
(6741, 'ubiquity', '/juːˈbɪkwɪti/', 'noun', '{"zh-TW":["無所不在；普遍存在"],"en":["the fact of appearing everywhere"]}', NULL, 'digital ubiquity / ubiquity of mobile devices / social media ubiquity', '[{"en":"The ubiquity of smartphones has transformed how businesses interact with customers.","zh-TW":"智慧型手機的普及改變了企業與客戶互動的方式。"},{"en":"Social media''s ubiquity makes it an essential tool for public communication.","zh-TW":"社交媒體的普及使其成為公共溝通的必要工具。"}]', '{"adjective":"ubiquitous","adverb":"ubiquitously"}', NULL, 3, 6741, NULL),
(6742, 'ultimate', '/ˈʌltɪmət/', 'adjective', '{"zh-TW":["最終的；終極的"],"en":["being the final or fundamental"]}', NULL, 'ultimate goal / ultimate decision / ultimate responsibility', '[{"en":"Our ultimate goal is customer satisfaction.","zh-TW":"我們的最終目標是客戶滿意。"},{"en":"The CEO has ultimate responsibility for the decision.","zh-TW":"執行長對這個決定承擔最終責任。"}]', '{"adjective":"ultimate","adverb":"ultimately","noun":"ultimatum"}', NULL, 3, 6742, NULL),
(6743, 'ultra vires', '/ˌʌltrə ˈvaɪriːz/', 'phrase', '{"zh-TW":["越權行為"],"en":["beyond one''s legal power or authority"]}', NULL, 'ultra vires act / ultra vires transaction / declare ultra vires', '[{"en":"The board''s decision was challenged as ultra vires.","zh-TW":"董事會的決定被質疑為越權行為。"},{"en":"Contracts that are ultra vires cannot be enforced.","zh-TW":"越權合約不能被執行。"}]', NULL, NULL, 4, 6743, NULL),
(6744, 'ultrasound', '/ˈʌltrəˌsaʊnd/', 'noun', '{"zh-TW":["超音波"],"en":["an imaging technique using high-frequency sound waves"]}', NULL, 'ultrasound scan / abdominal ultrasound', '[{"en":"The ultrasound confirmed the pregnancy at eight weeks.","zh-TW":"超音波確認了八週的懷孕情況。"},{"en":"An abdominal ultrasound checks organs such as the liver.","zh-TW":"腹部超音波檢查肝臟等器官。"}]', NULL, NULL, 4, 6744, NULL),
(6745, 'umami', '/''uːˈmɑːmi/', 'noun', '{"zh-TW":["鮮味；第五種基本味道"],"en":["a category of taste described as savory, associated with protein-rich foods"]}', NULL, 'umami flavor / umami-rich / enhance umami', '[{"en":"Soy sauce, mushrooms, and parmesan cheese are all rich in umami.","zh-TW":"醬油、蘑菇和帕瑪森起司都富含鮮味。"},{"en":"Chefs add a touch of umami to elevate the depth of their dishes.","zh-TW":"廚師添加一點鮮味來提升菜肴的深度。"}]', NULL, NULL, 2, 6745, NULL),
(6746, 'umbrella policy', '/ʌmˈbrelə ˈpɒlɪsi/', 'noun', '{"zh-TW":["綜合責任保險"],"en":["a broad liability insurance policy providing coverage beyond primary policies"]}', NULL, 'purchase an umbrella policy / umbrella policy limits', '[{"en":"The company purchased an umbrella policy to cover large liability claims.","zh-TW":"公司購買了綜合責任保險以涵蓋大額責任索賠。"},{"en":"An umbrella policy provides extra coverage beyond standard insurance limits.","zh-TW":"綜合責任保險在標準保險限額之外提供了額外保障。"}]', NULL, NULL, 5, 6746, NULL),
(6747, 'unanimous', '/juːˈnænɪməs/', 'adjective', '{"zh-TW":["一致的；無異議的"],"en":["fully in agreement"]}', NULL, 'unanimous decision / unanimous vote / unanimous support', '[{"en":"The board made a unanimous decision to proceed.","zh-TW":"董事會一致決定繼續進行。"},{"en":"The proposal received unanimous support.","zh-TW":"該提案獲得了一致支持。"}]', '{"noun":"unanimity","adjective":"unanimous","adverb":"unanimously"}', NULL, 3, 6747, NULL),
(6748, 'unauthorized access', '/ˌʌnˈɔːθəraɪzd ˈækses/', 'noun', '{"zh-TW":["未經授權的存取"],"en":["access to systems, data, or areas without proper permission"]}', NULL, 'prevent unauthorized access / unauthorized access incident', '[{"en":"Unauthorized access to financial systems was detected and blocked.","zh-TW":"對財務系統的未經授權存取被檢測並阻止了。"},{"en":"Multi-factor authentication reduces the risk of unauthorized access.","zh-TW":"多因素驗證降低了未經授權存取的風險。"}]', NULL, NULL, 5, 6748, NULL),
(6749, 'uncertainty', '/ʌnˈsɜːrtənti/', 'noun', '{"zh-TW":["不確定性"],"en":["the state of being uncertain; something not known or established"]}', NULL, 'economic uncertainty / policy uncertainty / reduce uncertainty', '[{"en":"Economic uncertainty caused many businesses to delay investment.","zh-TW":"經濟不確定性導致許多企業推遲投資。"},{"en":"Decision-making under uncertainty requires careful risk assessment.","zh-TW":"在不確定性下做決策需要仔細的風險評估。"}]', '{"adjective":"uncertain","adverb":"uncertainly"}', NULL, 4, 6749, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6750, 'undercut', '/ˌʌndərˈkʌt/', 'verb', '{"zh-TW":["削價競爭；壓低價格"],"en":["to price goods or services lower than competitors to gain business"]}', NULL, 'undercut the competition / undercut on price', '[{"en":"The new supplier undercut established players by 20% to win the contract.","zh-TW":"新供應商以低20%的價格削價競爭以贏得合約。"},{"en":"Undercutting may win short-term business but risks unsustainable margins.","zh-TW":"削價競爭可能贏得短期業務，但有利潤不可持續的風險。"}]', '{"noun":"undercutting"}', NULL, 3, 6750, NULL),
(6751, 'underestimate', '/ˌʌndərˈestɪmeɪt/', 'verb', '{"zh-TW":["低估"],"en":["to estimate as less than the actual value"]}', NULL, 'underestimate the cost / underestimate the risk / never underestimate', '[{"en":"Never underestimate the importance of customer feedback.","zh-TW":"永遠不要低估客戶回饋的重要性。"},{"en":"We underestimated the project timeline.","zh-TW":"我們低估了專案的時程。"}]', '{"noun":"underestimation","verb":"underestimate"}', NULL, 5, 6751, NULL),
(6752, 'underfunded pension', '/ˌʌndəˈfʌndɪd ˈpenʃən/', 'noun', '{"zh-TW":["資金不足的養老金"],"en":["a pension fund where liabilities exceed assets available to pay future obligations"]}', NULL, 'address an underfunded pension / underfunded pension liability', '[{"en":"The company''s underfunded pension liability reached $200 million.","zh-TW":"公司的資金不足養老金負債達到了2億元。"},{"en":"An underfunded pension is a significant risk disclosed in financial statements.","zh-TW":"資金不足的養老金是財務報表中披露的重大風險。"}]', NULL, NULL, 5, 6752, NULL),
(6753, 'undergo', '/ˌʌndərˈɡoʊ/', 'verb', '{"zh-TW":["經歷；接受"],"en":["to experience or be subjected to"]}', NULL, 'undergo changes / undergo training / undergo surgery', '[{"en":"The company is undergoing major restructuring.","zh-TW":"公司正在經歷重大重組。"},{"en":"All employees must undergo safety training.","zh-TW":"所有員工都必須接受安全訓練。"}]', '{"verb":"undergo"}', NULL, 3, 6753, NULL),
(6754, 'undergraduate', '/ˌʌndərˈɡrædʒuɪt/', 'noun', '{"zh-TW":["大學生；本科生","大學生"],"en":["a university student who has not yet received a first degree","a student studying for a first degree"]}', NULL, 'undergraduate degree / undergraduate program; undergraduate program / undergraduate student', '[{"en":"She completed her undergraduate degree in economics.","zh-TW":"她完成了經濟學的學士學位。"},{"en":"We recruit from top undergraduate programs.","zh-TW":"我們從頂尖大學課程招聘。"},{"en":"She''s an undergraduate at Oxford.","zh-TW":"她是牛津大學的大學生。"},{"en":"The undergraduate program lasts four years.","zh-TW":"大學學程為期四年。"}]', '{"noun":"undergraduate","adjective":"undergraduate"}', NULL, 5, 6754, NULL),
(6755, 'underline', '/ˌʌndərˈlaɪn/', 'verb', '{"zh-TW":["強調；突顯"],"en":["to emphasize; to draw attention to"]}', NULL, 'underline the importance / underline the need', '[{"en":"The report underlines the need for investment.","zh-TW":"報告強調了投資的必要性。"},{"en":"Recent events underline the importance of planning.","zh-TW":"近期事件突顯了規劃的重要性。"}]', '{"verb":"underline"}', NULL, 3, 6755, NULL),
(6756, 'undermine', '/ˌʌndərˈmaɪn/', 'verb', '{"zh-TW":["破壞；削弱"],"en":["to weaken or damage gradually"]}', NULL, 'undermine confidence / undermine authority / undermine efforts', '[{"en":"The scandal undermined public confidence.","zh-TW":"醜聞破壞了公眾信心。"},{"en":"Internal conflicts undermine team productivity.","zh-TW":"內部衝突削弱了團隊生產力。"}]', '{"verb":"undermine"}', NULL, 3, 6756, NULL),
(6757, 'underperform', '/ˌʌndərpəˈfɔːrm/', 'verb', '{"zh-TW":["表現不佳；低於預期"],"en":["to perform less well than expected or required"]}', NULL, 'underperform expectations / underperform the market', '[{"en":"The division underperformed its targets for the third consecutive quarter.","zh-TW":"該部門連續第三個季度未能達到目標。"},{"en":"The stock continued to underperform the market index.","zh-TW":"該股票繼續低於市場指數的表現。"}]', '{"noun":"underperformance","adjective":"underperforming"}', NULL, 4, 6757, NULL),
(6758, 'underperformance', '/ˌʌndərpəˈfɔːrməns/', 'noun', '{"zh-TW":["績效不佳；表現欠佳"],"en":["the failure to achieve expected standards of performance"]}', NULL, 'address underperformance / underperformance of a fund', '[{"en":"The fund''s underperformance relative to the index prompted a management review.","zh-TW":"基金相對於指數的績效不佳促使了管理層審查。"},{"en":"A performance improvement plan is triggered when underperformance is identified.","zh-TW":"當識別到績效不佳時，績效改進計劃被觸發。"}]', '{"verb":"underperform"}', NULL, 5, 6758, NULL),
(6759, 'underperforming', '/ˌʌndərpəˈfɔːrmɪŋ/', 'adjective', '{"zh-TW":["表現不佳的；未達標的"],"en":["performing less well than expected or required"]}', NULL, 'underperforming asset / underperforming division / underperforming portfolio', '[{"en":"The board decided to divest the underperforming business unit.","zh-TW":"董事會決定剝離表現不佳的業務部門。"},{"en":"Underperforming loans are flagged for restructuring or write-off.","zh-TW":"表現不佳的貸款被標記為重組或核銷對象。"}]', '{"verb":"underperform","noun":"underperformance"}', NULL, 5, 6759, NULL),
(6760, 'underprice', '/ˌʌndərˈpraɪs/', 'verb', '{"zh-TW":["低估定價；定價過低"],"en":["to set a price for a product or service below its true value"]}', NULL, 'underprice a product / risk of underpricing', '[{"en":"Underpricing the new product led to rapid adoption but thin margins.","zh-TW":"對新產品低估定價導致了迅速採用但利潤微薄。"},{"en":"Competitors underpriced the market to gain initial share.","zh-TW":"競爭對手對市場低估定價以獲取初始份額。"}]', '{"noun":"underpricing","adjective":"underpriced"}', NULL, 4, 6760, NULL),
(6761, 'understand', 'ˌʌndərˈstænd', 'verb', '{"zh-TW":["理解；明白","接受"],"en":["to know the meaning of","to accept"]}', NULL, 'understand a concept/policy', '[{"en":"I fully understand your concern.","zh-TW":"我完全理解您的擔憂。"}]', '{"noun":"understanding","adjective":"understandable","adverb":"understandably"}', NULL, 4, 6761, NULL),
(6762, 'undertake', '/ˌʌndərˈteɪk/', 'verb', '{"zh-TW":["承擔；從事"],"en":["to commit to doing something"]}', NULL, 'undertake a project / undertake research / undertake responsibility', '[{"en":"We undertook a comprehensive market study.","zh-TW":"我們進行了全面的市場研究。"},{"en":"The firm undertook the renovation project.","zh-TW":"該公司承擔了翻新工程。"}]', '{"noun":"undertaking","verb":"undertake"}', NULL, 3, 6762, NULL),
(6763, 'undervalued', '/ˌʌndərˈvæljuːd/', 'adjective', '{"zh-TW":["被低估的；估值偏低的"],"en":["priced below its true intrinsic or market value"]}', NULL, 'undervalued stock / undervalued currency / undervalued asset', '[{"en":"Value investors seek undervalued stocks that the market has overlooked or mispriced.","zh-TW":"價值投資者尋找市場忽視或錯誤定價的被低估股票。"},{"en":"An undervalued currency gives a country''s exports a competitive price advantage.","zh-TW":"被低估的貨幣使一個國家的出口具有競爭性的價格優勢。"}]', '{"verb":"undervalue"}', NULL, 4, 6763, NULL),
(6764, 'underwater', '/ˌʌndərˈwɔːtər/', 'adjective', '{"zh-TW":["資不抵債的；虧損的"],"en":["having a market value less than the outstanding debt; describing a position with a loss"]}', NULL, 'underwater mortgage / underwater stock options / deeply underwater', '[{"en":"Homeowners with underwater mortgages owe more than their properties are worth.","zh-TW":"持有水下抵押貸款的房主欠款金額超過其房產的價值。"},{"en":"The employee''s stock options were underwater because the share price fell below the exercise price.","zh-TW":"由於股價跌破行使價，該員工的股票期權已陷入虧損狀態。"}]', NULL, NULL, 4, 6764, NULL),
(6765, 'underway', '/ˌʌndərˈweɪ/', 'adjective, adverb', '{"zh-TW":["進行中的"],"en":["having started and in progress"]}', NULL, 'get underway / already underway / well underway', '[{"en":"Construction is already underway at the new site.","zh-TW":"新址的建設已經在進行中。"},{"en":"Plans are well underway for the expansion.","zh-TW":"擴張計畫正在順利進行中。"}]', '{"adjective":"underway"}', NULL, 3, 6765, NULL),
(6766, 'underwrite', '/ˌʌndərˈraɪt/', 'verb', '{"zh-TW":["承保；擔保"],"en":["to accept financial responsibility for","to insure"]}', NULL, 'underwrite a loan / underwrite an IPO', '[{"en":"The bank agreed to underwrite the bond issue.","zh-TW":"銀行同意承銷債券發行。"},{"en":"Insurance companies underwrite risk.","zh-TW":"保險公司承保風險。"}]', '{"verb":"underwrite","noun":"underwriter","noun2":"underwriting"}', NULL, 4, 6766, NULL),
(6767, 'underwriter', '/ˈʌndərˌraɪtər/', 'noun', '{"zh-TW":["承銷商；保險商"],"en":["a financial institution that manages the sale of new securities"]}', NULL, 'lead underwriter / underwriter agreement / insurance underwriter', '[{"en":"The bank acted as lead underwriter for the bond issuance.","zh-TW":"銀行擔任債券發行的主承銷商。"},{"en":"Underwriters priced the IPO at $20 per share.","zh-TW":"承銷商將首次公開募股定價為每股20美元。"}]', '{"verb":"underwrite","noun":"underwriting"}', NULL, 4, 6767, NULL),
(6768, 'underwriting', '/ˈʌndərˌraɪtɪŋ/', 'noun', '{"zh-TW":["承保；核保"],"en":["the process of evaluating and assuming financial risk for a fee"]}', NULL, 'insurance underwriting / mortgage underwriting / underwriting criteria', '[{"en":"Underwriting standards were tightened after the financial crisis.","zh-TW":"金融危機後，核保標準收緊了。"},{"en":"The underwriting process determines the premium rate and coverage.","zh-TW":"核保流程確定保費費率和保障範圍。"}]', '{"verb":"underwrite","noun":"underwriter"}', NULL, 4, 6768, NULL),
(6769, 'underwriting risk', '/ˈʌndəraɪtɪŋ rɪsk/', 'noun', '{"zh-TW":["承銷風險"],"en":["the risk taken by an underwriter in guaranteeing the sale of a financial instrument"]}', NULL, 'manage underwriting risk / underwriting risk assessment', '[{"en":"The bank reduced underwriting risk by syndicating the bond issuance.","zh-TW":"銀行通過聯合發行債券降低了承銷風險。"},{"en":"Underwriting risk is higher in volatile markets with uncertain demand.","zh-TW":"在需求不確定的波動市場中，承銷風險較高。"}]', NULL, NULL, 5, 6769, NULL),
(6770, 'unemployment', '/ˌʌnɪmˈplɔɪmənt/', 'noun', '{"zh-TW":["失業；失業率"],"en":["the state of being without a job"]}', NULL, 'unemployment rate / unemployment benefits / reduce unemployment', '[{"en":"The unemployment rate dropped to 4%.","zh-TW":"失業率降至4%。"},{"en":"Government programs aim to reduce unemployment.","zh-TW":"政府計畫旨在降低失業率。"}]', '{"noun":"unemployment, employment","adjective":"unemployed, employed","verb":"employ"}', NULL, 4, 6770, NULL),
(6771, 'unemployment rate', '/''ʌnɪmˌplɔɪmənt reɪt/', 'noun', '{"zh-TW":["失業率"],"en":["the percentage of the total labor force that is unemployed but actively seeking employment"]}', NULL, 'lower the unemployment rate / unemployment rate rises / measure the unemployment rate', '[{"en":"The unemployment rate dropped to a record low following several months of strong job growth.","zh-TW":"在幾個月強勁的就業增長之後，失業率降至創記錄的低點。"},{"en":"An increase in the unemployment rate often signals an economic slowdown.","zh-TW":"失業率上升通常表示經濟放緩。"}]', '{"adjective":"unemployed","verb":"employ"}', NULL, 5, 6771, NULL),
(6772, 'unencumbered', '/ˌʌnɪnˈkʌmbərd/', 'adjective', '{"zh-TW":["無負擔的；無抵押的"],"en":["not restricted or burdened by debt or legal obligations"]}', NULL, 'unencumbered assets / unencumbered cash / unencumbered title', '[{"en":"Unencumbered assets can be freely sold or pledged as collateral.","zh-TW":"未設抵押的資產可以自由出售或作為抵押品質押。"},{"en":"The bank required a certain amount of unencumbered liquidity to meet regulatory requirements.","zh-TW":"銀行需要一定數量的無抵押流動資金，以滿足監管要求。"}]', NULL, NULL, 4, 6772, NULL),
(6773, 'unequivocal', '/ˌʌnɪˈkwɪvəkəl/', 'adjective', '{"zh-TW":["明確的；毫不含糊的"],"en":["leaving no doubt; clear and unambiguous"]}', NULL, 'unequivocal evidence / unequivocal statement / unequivocal support', '[{"en":"The data provide unequivocal evidence for the hypothesis.","zh-TW":"這些數據為該假設提供了明確的證據。"},{"en":"The committee issued an unequivocal rejection of the proposal.","zh-TW":"委員會對該提案發出明確的拒絕聲明。"}]', '{"adverb":"unequivocally"}', NULL, 4, 6773, NULL),
(6774, 'unfair dismissal', '/ʌnˈfeər dɪsˈmɪsəl/', 'noun', '{"zh-TW":["不公平解雇"],"en":["termination of employment that violates legal or contractual protections"]}', NULL, 'claim unfair dismissal / unfair dismissal case', '[{"en":"The employee filed a lawsuit for unfair dismissal.","zh-TW":"員工提起了不公平解雇訴訟。"},{"en":"Unfair dismissal claims can result in compensation awards.","zh-TW":"不公平解雇索賠可能導致賠償裁決。"}]', NULL, NULL, 5, 6774, NULL),
(6775, 'unforeseen', '/ˌʌnfɔːrˈsiːn/', 'adjective', '{"zh-TW":["無法預見的；意外的"],"en":["not anticipated or predicted"]}', NULL, 'unforeseen circumstances / unforeseen problems / unforeseen delays', '[{"en":"Unforeseen circumstances caused the project delay.","zh-TW":"不可預見的情況導致專案延遲。"},{"en":"We must prepare for unforeseen risks.","zh-TW":"我們必須為不可預見的風險做準備。"}]', '{"adjective":"unforeseen, foreseen","verb":"foresee"}', NULL, 4, 6775, NULL),
(6776, 'unfunded pension liability', '/ʌnˈfʌndɪd ˈpenʃən laɪˈæbɪlɪti/', 'noun', '{"zh-TW":["未撥備養老金負債"],"en":["the shortfall between a pension fund''s obligations and its assets"]}', NULL, 'disclose unfunded pension liability / manage unfunded pension liability', '[{"en":"The company disclosed a significant unfunded pension liability in its accounts.","zh-TW":"公司在賬目中披露了重大的未撥備養老金負債。"},{"en":"Unfunded pension liabilities increase the financial risk for employers.","zh-TW":"未撥備養老金負債增加了雇主的財務風險。"}]', NULL, NULL, 5, 6776, NULL),
(6777, 'uniform', '/ˈjuːnɪfɔːrm/', 'adjective, noun', '{"zh-TW":["統一的；一致的","制服"],"en":["consistent; not varying","a distinctive set of clothes"]}', NULL, 'uniform standard / uniform policy / uniform across', '[{"en":"The company enforces uniform quality standards.","zh-TW":"公司執行統一的品質標準。"},{"en":"Pricing must be uniform across all regions.","zh-TW":"定價在所有地區必須一致。"}]', '{"noun":"uniform, uniformity","adjective":"uniform","adverb":"uniformly"}', NULL, 3, 6777, 473),
(6778, 'uniform standard', '/ˈjuːnɪfɔːrm ˈstændərd/', 'noun', '{"zh-TW":["統一標準"],"en":["a consistent set of rules or requirements applied equally across an organization"]}', NULL, 'apply uniform standards / set uniform standards', '[{"en":"Uniform standards ensure consistent quality across all production sites.","zh-TW":"統一標準確保了所有生產地點的一致品質。"},{"en":"The company adopted uniform standards for supplier evaluation.","zh-TW":"公司採用了統一標準進行供應商評估。"}]', NULL, NULL, 5, 6778, NULL),
(6779, 'unilateral', '/ˌjuːnɪˈlætərəl/', 'adjective', '{"zh-TW":["單方面的；片面的"],"en":["decided or taken by one party without consulting others"]}', NULL, 'unilateral decision / unilateral termination', '[{"en":"The unilateral termination of the contract was challenged in court.","zh-TW":"合約的單方面終止在法庭上受到了質疑。"},{"en":"A unilateral change to the terms is not permitted without consent.","zh-TW":"未經同意不得單方面更改條款。"}]', '{"adverb":"unilaterally"}', NULL, 4, 6779, NULL),
(6780, 'unique', '/juːˈniːk/', 'adjective', '{"zh-TW":["獨特的；唯一的"],"en":["being the only one of its kind"]}', NULL, 'unique opportunity / unique selling point / unique feature', '[{"en":"Each product has a unique serial number.","zh-TW":"每個產品都有獨特的序號。"},{"en":"Our unique selling point is personalized service.","zh-TW":"我們的獨特賣點是個人化服務。"}]', '{"noun":"uniqueness","adjective":"unique","adverb":"uniquely"}', NULL, 2, 6780, 474),
(6781, 'unique selling point', '/juːˈniːk ˈselɪŋ pɔɪnt/', 'noun', '{"zh-TW":["獨特賣點"],"en":["a distinct feature that differentiates a product from its competitors"]}', NULL, 'identify your USP / communicate your USP / strong USP', '[{"en":"Free lifetime support is the product''s unique selling point.","zh-TW":"免費終身支援是該產品的獨特賣點。"},{"en":"The brand''s unique selling point is its environmentally friendly packaging.","zh-TW":"該品牌的獨特賣點是其環保包裝。"}]', '{"abbreviation":"USP"}', NULL, 5, 6781, NULL),
(6782, 'unit', '/ˈjuːnɪt/', 'noun', '{"zh-TW":["單位；部門"],"en":["an individual thing; a section of an organization"]}', NULL, 'business unit / per unit / unit cost', '[{"en":"The cost per unit decreased with higher volume.","zh-TW":"隨著產量增加，單位成本下降。"},{"en":"The marketing unit launched a new campaign.","zh-TW":"行銷部門推出了新活動。"}]', '{"noun":"unit, unity","verb":"unite","adjective":"united"}', NULL, 1, 6782, NULL),
(6783, 'unit cost', '/ˈjuːnɪt kɒst/', 'noun', '{"zh-TW":["單位成本"],"en":["the cost of producing one unit of a product"]}', NULL, 'reduce unit cost / calculate unit cost', '[{"en":"Increasing production volume can reduce the unit cost.","zh-TW":"增加生產量可以降低單位成本。"},{"en":"The unit cost of the product decreased with automation.","zh-TW":"自動化降低了產品的單位成本。"}]', NULL, NULL, 3, 6783, NULL),
(6784, 'unit economics', '/ˈjuːnɪt ˌɪkəˈnɒmɪks/', 'noun', '{"zh-TW":["單位經濟學；單位盈利模型"],"en":["the revenue and cost associated with one unit of a product or customer"]}', NULL, 'analyze unit economics / improve unit economics', '[{"en":"The startup''s unit economics showed strong margins at scale.","zh-TW":"新創公司的單位經濟學在規模化時顯示出強勁的利潤率。"},{"en":"Positive unit economics are essential for a sustainable business model.","zh-TW":"正向的單位經濟學對可持續的商業模式至關重要。"}]', NULL, NULL, 5, 6784, NULL),
(6785, 'unit price', '/ˈjuːnɪt praɪs/', 'noun', '{"zh-TW":["單價"],"en":["the price charged for a single unit of a product"]}', NULL, 'calculate unit price / negotiate unit price', '[{"en":"The unit price was reduced to $8 for orders above 1000 pieces.","zh-TW":"訂購超過1000件時單價降至8元。"},{"en":"A lower unit price increases competitiveness but requires higher volume.","zh-TW":"較低的單價提高了競爭力，但需要更高的銷量。"}]', NULL, NULL, 4, 6785, NULL),
(6786, 'unit test', '/ˈjuːnɪt test/', 'noun', '{"zh-TW":["單元測試"],"en":["a test that verifies the functionality of a single component"]}', NULL, 'write unit tests / run unit tests / unit test coverage', '[{"en":"Writing unit tests early prevents many bugs from reaching production.","zh-TW":"早期編寫單元測試防止許多錯誤進入生產環境。"},{"en":"The developer increased unit test coverage to ninety percent.","zh-TW":"開發者將單元測試覆蓋率提高到百分之九十。"}]', '{"verb":"unit test","adjective":"unit-tested"}', NULL, 3, 6786, NULL),
(6787, 'unitranche', '/ˌjuːnɪˈtrænʃ/', 'noun', '{"zh-TW":["單一層級融資"],"en":["a hybrid loan combining senior and subordinated debt into one facility"]}', NULL, 'unitranche facility / unitranche deal / unitranche lender', '[{"en":"Unitranche financing simplifies the capital structure for mid-market companies.","zh-TW":"單一層級融資簡化了中型市場公司的資本結構。"},{"en":"Private credit funds often provide unitranche solutions.","zh-TW":"私人信貸基金通常提供單一層級融資解決方案。"}]', NULL, NULL, 4, 6787, NULL),
(6788, 'universal', '/ˌjuːnɪˈvɜːrsl/', 'adjective', '{"zh-TW":["普遍的；全球的"],"en":["relating to all people or things"]}', NULL, 'universal access / universal standard / universal appeal', '[{"en":"The policy aims for universal access to healthcare.","zh-TW":"該政策旨在實現全民醫療保健。"},{"en":"Good customer service has universal appeal.","zh-TW":"良好的客戶服務具有普遍的吸引力。"}]', '{"noun":"universality","adjective":"universal","adverb":"universally"}', NULL, 3, 6788, 945),
(6789, 'universal basic income', '/ˌjuːnɪˈvɜːrsəl ˈbeɪsɪk ˈɪnkʌm/', 'noun', '{"zh-TW":["全民基本收入"],"en":["a regular cash payment given unconditionally to all citizens regardless of income or employment"]}', NULL, 'implement universal basic income / universal basic income pilot / debate universal basic income', '[{"en":"Proponents of universal basic income argue it can replace complex welfare systems.","zh-TW":"全民基本收入的支持者認為，它可以取代複雜的福利體系。"},{"en":"Pilot programs for universal basic income showed improvements in well-being.","zh-TW":"全民基本收入的試點計畫顯示了生活水平的改善。"}]', NULL, NULL, 5, 6789, NULL),
(6790, 'university', '/ˌjuːnɪˈvɜːrsɪti/', 'noun', '{"zh-TW":["大學"],"en":["an institution of higher learning"]}', NULL, 'go to university / university degree', '[{"en":"She graduated from a top university.","zh-TW":"她從頂尖大學畢業。"},{"en":"Which university did you attend?","zh-TW":"你讀哪所大學？"}]', NULL, NULL, 4, 6790, NULL),
(6791, 'unlisted company', '/ʌnˈlɪstɪd ˈkʌmpəni/', 'noun', '{"zh-TW":["非上市公司"],"en":["a company that is not listed on a public stock exchange"]}', NULL, 'valuation of an unlisted company / unlisted company financing', '[{"en":"Unlisted companies are valued using comparable company or discounted cash flow analysis.","zh-TW":"非上市公司使用可比公司或折現現金流分析進行估值。"},{"en":"Unlisted companies have fewer disclosure requirements than public companies.","zh-TW":"非上市公司比上市公司有更少的披露要求。"}]', '{"synonym":"private company","opposite":"listed company"}', NULL, 5, 6791, NULL),
(6792, 'unprecedented', '/ʌnˈpresɪdentɪd/', 'adjective', '{"zh-TW":["前所未有的；空前的"],"en":["never done or known before"]}', NULL, 'unprecedented growth / unprecedented challenge / unprecedented demand', '[{"en":"The company experienced unprecedented demand.","zh-TW":"公司經歷了前所未有的需求。"},{"en":"We face unprecedented challenges in the market.","zh-TW":"我們在市場上面臨空前的挑戰。"}]', '{"adjective":"unprecedented, precedented"}', NULL, 5, 6792, NULL),
(6793, 'unprecedented growth', '/''ʌnˌpresɪdentɪd ɡrəʊθ/', 'noun', '{"zh-TW":["前所未有的增長；破紀錄的成長"],"en":["growth at a level or rate that has never occurred before"]}', NULL, 'experience unprecedented growth / fuel unprecedented growth / period of unprecedented growth', '[{"en":"The tech startup experienced unprecedented growth of three hundred percent in just one year.","zh-TW":"這家科技初創公司在短短一年內實現了三百%的前所未有的增長。"},{"en":"Unprecedented growth in online retail has transformed the global shopping landscape.","zh-TW":"網上零售的前所未有的增長改變了全球購物格局。"}]', NULL, NULL, 5, 6793, NULL),
(6794, 'unsaturated fat', '/''ʌnˌsætʃəreɪtɪd fæt/', 'noun', '{"zh-TW":["不飽和脂肪"],"en":["a type of fat found in plant foods and fish, considered healthier than saturated fat"]}', NULL, 'include unsaturated fats / source of unsaturated fat / unsaturated fat benefit', '[{"en":"Olive oil and avocado are rich sources of healthy unsaturated fats.","zh-TW":"橄欖油和牛油果是健康不飽和脂肪的豐富來源。"},{"en":"Replacing saturated fats with unsaturated fats can benefit cardiovascular health.","zh-TW":"用不飽和脂肪代替飽和脂肪可以改善心血管健康。"}]', '{"adjective":"unsaturated"}', NULL, 5, 6794, NULL),
(6795, 'unsecured bond', '/ʌnˈsɪkjʊərd bɒnd/', 'noun', '{"zh-TW":["無擔保債券"],"en":["a bond not backed by specific collateral, relying only on the issuer''s creditworthiness"]}', NULL, 'issue an unsecured bond / unsecured bond yield', '[{"en":"The company issued unsecured bonds at a higher interest rate.","zh-TW":"公司以較高的利率發行了無擔保債券。"},{"en":"Unsecured bondholders rank below secured creditors in insolvency.","zh-TW":"在破產時，無擔保債券持有人排在有擔保債權人之後。"}]', '{"opposite":"secured bond"}', NULL, 5, 6795, NULL),
(6796, 'unsecured debt', '/ˌʌnsɪˈkjʊəd det/', 'noun', '{"zh-TW":["無擔保債務"],"en":["debt not backed by collateral and dependent solely on the borrower''s creditworthiness"]}', NULL, 'take on unsecured debt / unsecured debt holders / priority of unsecured debt', '[{"en":"Unsecured debt typically carries a higher interest rate to compensate for the greater risk.","zh-TW":"無擔保債務通常承擔較高的利率，以補償較大的風險。"},{"en":"Unsecured debt holders receive lower priority than secured creditors in bankruptcy.","zh-TW":"在破產程序中，無擔保債務持有人的優先順序低於有擔保債權人。"}]', NULL, NULL, 5, 6796, NULL),
(6797, 'unsystematic risk', '/ˌʌnsɪstəˈmætɪk rɪsk/', 'noun', '{"zh-TW":["非系統性風險；個別風險"],"en":["risk specific to a particular company or industry that can be reduced through diversification"]}', NULL, 'manage unsystematic risk / diversify to reduce unsystematic risk', '[{"en":"Diversifying across sectors reduces unsystematic risk in a portfolio.","zh-TW":"跨行業多元化降低了投資組合中的非系統性風險。"},{"en":"Unsystematic risk includes management changes and product recalls.","zh-TW":"非系統性風險包括管理層變動和產品召回。"}]', '{"opposite":"systematic risk"}', NULL, 5, 6797, NULL),
(6798, 'unveil', '/ʌnˈveɪl/', 'verb', '{"zh-TW":["揭露；公布"],"en":["to show or reveal something new"]}', NULL, 'unveil a plan / unveil a product / unveil a strategy', '[{"en":"The CEO unveiled the new product line at the conference.","zh-TW":"執行長在會議上公布了新產品線。"},{"en":"The government unveiled its economic recovery plan.","zh-TW":"政府公布了經濟復甦計畫。"}]', '{"verb":"unveil","noun":"unveiling"}', NULL, 2, 6798, NULL),
(6799, 'unwind', '/ʌnˈwaɪnd/', 'verb', '{"zh-TW":["平倉；解除"],"en":["to reverse or close out a financial position or transaction"]}', NULL, 'unwind a position / unwind a trade', '[{"en":"The hedge fund began to unwind its leveraged positions.","zh-TW":"對沖基金開始平倉其槓桿倉位。"},{"en":"The transaction was unwound after the deal fell through.","zh-TW":"交易在失敗後被解除了。"}]', '{"noun":"unwinding","adjective":"unwound"}', NULL, 2, 6799, NULL);